// /frontend-react/src/App.js

import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import MedicalDashboard from './components/MedicalDashboard';
import AppointmentFlow from './components/AppointmentFlow';
import TransportStatus from './components/TransportStatus';
import MedicineReminder from './components/MedicineReminder';
import HeaderBar from './components/HeaderBar';
import SideMenu from './components/SideMenu'; // NEW IMPORT

// Mock data (remains the same)
const mockAppointmentData = { date: 'Dec 10', time: '10:00 AM', hasTransportBooked: false };

function App() {
    const [currentPage, setCurrentPage] = useState('dashboard'); 
    const [isEasyMode] = useState(true); 
    // NEW STATE: Control the visibility of the side menu
    const [isMenuOpen, setIsMenuOpen] = useState(false); 

    const handleNotificationClick = () => {
        setCurrentPage('appointment');
    };

    const renderPage = () => {
        // --- Level 1: Main Dashboard (4 Icons) ---
        if (currentPage === 'dashboard') {
            return (
                <Dashboard isEasyMode={isEasyMode} goToMedical={() => setCurrentPage('medical-dashboard')} />
            );
        }

        // --- Level 2: Medical Sub-Dashboard (3 Icons) ---
        if (currentPage === 'medical-dashboard') {
             return (
                <MedicalDashboard isEasyMode={isEasyMode} goToPage={setCurrentPage} />
            );
        }
        // --- Level 3: Feature Pages ---
        if (currentPage === 'appointment') {
            return (
                <AppointmentFlow
                    isEasyMode={isEasyMode}
                    appointment={mockAppointmentData}
                    goToTransportStatus={() => setCurrentPage('transport')} 
                    goToMedicalDashboard={() => setCurrentPage('medical-dashboard')} 
                />
            );
        }
        if (currentPage === 'transport') {
            return (
                <TransportStatus
                    isEasyMode={isEasyMode}
                    goToAppointmentFlow={() => setCurrentPage('appointment')} 
                    goToMedicalDashboard={() => setCurrentPage('medical-dashboard')} 
                />
            );
        }
        if (currentPage === 'medicine') {
            return (
                <MedicineReminder 
                    isEasyMode={isEasyMode} 
                    goToPage={setCurrentPage} 
                />
            );
        }
        // Fallback or other pages
        return null; 
    };

    // Styles to hide the scrollbar while keeping scrolling active
    const scrollbarHiddenStyle = {
        'overflowY': 'auto', 
        'msOverflowStyle': 'none', 
        'scrollbarWidth': 'none', 
        // Note: For Chrome/Safari, the ::-webkit-scrollbar rule should be applied via global CSS.
    };
    
    // Determine title and back destination for the HeaderBar based on current page
    const getHeaderProps = () => {
        let title = currentPage.replace('-', ' ').toUpperCase();
        let backAction = null;

        if (currentPage === 'appointment' || currentPage === 'transport' || currentPage === 'medicine') {
             backAction = () => setCurrentPage('medical-dashboard');
        } else if (currentPage === 'medical-dashboard') {
             backAction = () => setCurrentPage('dashboard');
        }
        return { title, backAction };
    };

    const { title, backAction } = getHeaderProps();

    return (
        // Outer container: Centers the frame on the desktop screen
        <div style={{
            padding: '20px',
            backgroundColor: '#f0f0f0', 
            minHeight: '100vh', 
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center', 
        }}>
            
            {/* 📱 Phone Casing / Outer Frame */}
            <div 
                style={{
                    maxWidth: '400px', 
                    width: '100%',
                    height: '750px', 
                    margin: '20px 0',
                    border: '15px solid #333', 
                    borderRadius: '40px', 
                    boxShadow: '0 10px 40px rgba(0,0,0,0.5)',
                    backgroundColor: '#000', 
                    position: 'relative',
                    flexShrink: 0,
                }}
            >
                {/* Mock Speaker/Notch (Visual Detail) */}
                <div style={{
                    position: 'absolute',
                    top: '5px',
                    left: '50%',
                    transform: 'translateX(-50%)',
                    width: '100px',
                    height: '8px',
                    backgroundColor: '#444',
                    borderRadius: '4px',
                    zIndex: 20
                }}></div>

                {/* Inner App Content Screen (Scrollable area) */}
                <div 
                    style={{
                        height: '100%',
                        width: '100%',
                        backgroundColor: '#ffffff',
                        borderRadius: '25px', 
                        boxSizing: 'border-box',
                        ...scrollbarHiddenStyle,
                    }}
                    className={`App ${isEasyMode ? 'easy-mode-theme' : 'standard-theme'}`}
                >
                    {/* RENDER THE SIDE MENU FIRST (above all other page content) */}
                    <SideMenu
                        isEasyMode={isEasyMode}
                        isOpen={isMenuOpen}
                        onClose={() => setIsMenuOpen(false)}
                        goToPage={setCurrentPage}
                    />

                    {/* Conditional HeaderBar Rendering */}
                    {currentPage !== 'dashboard' && (
                        <HeaderBar 
                            title={title}
                            onBackClick={backAction} // Function or null
                            onMenuClick={() => setIsMenuOpen(true)} // Opens the side menu
                            isEasyMode={isEasyMode}
                        />
                    )}
                    
                    {/* Mock Notification Banner */}
                    {currentPage === 'dashboard' && (
                        <div 
                            onClick={handleNotificationClick}
                            style={{ 
                                padding: '15px', 
                                backgroundColor: '#ffdddd', 
                                color: 'red',
                                textAlign: 'center',
                                cursor: 'pointer',
                                fontSize: isEasyMode ? '28px' : '16px',
                                fontWeight: 'bold',
                                borderBottom: '2px solid red',
                                position: 'sticky', 
                                top: 0,
                                zIndex: 10
                            }}
                        >
                            🚨 **NOTIFICATION: Appointment Soon! Tap Here!** 🚨
                        </div>
                    )}
                    
                    {renderPage()}
                </div>
            </div>
        </div>
    );
}

export default App;
